import socket
import json
import random
import string

def generate_id(length=17):
    return ''.join(random.choice(string.ascii_lowercase + string.digits) for _ in range(length))

def send_message(sock, msg):
    sock.send((json.dumps(msg) + '\n').encode())

def receive_message(sock):
    data = b''
    while True:
        chunk = sock.recv(4096)
        if not chunk:
            break
        data += chunk
        if b'\n' in data:
            break
    return data.decode().strip()

# Connect to the Meteor server
sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
sock.connect(('web.chal.csaw.io', 5000))

# Initial connection message
connect_msg = {
    "msg": "connect",
    "version": "1",
    "support": ["1", "pre2", "pre1"]
}
send_message(sock, connect_msg)
print("Connect response:", receive_message(sock))

# Register new user
register_msg = {
    "msg": "method",
    "method": "createUser",
    "params": [{
        "username": "test",
        "password": "test123",
        "profile": {}
    }],
    "id": generate_id()
}
send_message(sock, register_msg)
print("Register response:", receive_message(sock))

sock.close()

import socket
import json
import random
import string

def generate_id(length=17):
    return ''.join(random.choice(string.ascii_lowercase + string.digits) for _ in range(length))

def send_message(sock, msg):
    sock.send((json.dumps(msg) + '\n').encode())

def receive_message(sock):
    data = b''
    while True:
        chunk = sock.recv(4096)
        if not chunk:
            break
        data += chunk
        if b'\n' in data:
            break
    return data.decode().strip()

# Connect to the Meteor server
sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
sock.connect(('web.chal.csaw.io', 5000))

# Initial connection message
connect_msg = {
    "msg": "connect",
    "version": "1",
    "support": ["1"]
}
send_message(sock, connect_msg)
print("Connect response:", receive_message(sock))

# Try to register using the accounts-password createUser method
