            "algorithm": "md5"
        }
    }],
    "id": generate_id()
}
send_message(sock, register_msg)
print("Register response:", receive_message(sock))

# Subscribe to the Meteor.users collection
sub_msg = {
    "msg": "sub",
    "name": "meteor.user",
    "params": [],
    "id": generate_id()
}
send_message(sock, sub_msg)
print("Subscribe response:", receive_message(sock))

